public class Solution {
    public static int[] divideWithRemainder(int dividend, int divisor) {
        if (divisor == 0) {
            throw new ArithmeticException("Division by zero");
        }
        return new int[]{dividend / divisor, dividend % divisor};
    }

    public static void main(String[] args) {
        int[] result = divideWithRemainder(23, 5);
        System.out.println("Method called successfully");
        System.out.println("Quotient: " + result[0] + ", Remainder: " + result[1]);
    }
}

public class Solution {
    static class Coordinate {
        public final int x;
        public final int y;

        public Coordinate(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static Coordinate translate(Coordinate p, int dx, int dy) {
        return new Coordinate(p.x + dx, p.y + dy);
    }

    public static void main(String[] args) {
        Coordinate origin = new Coordinate(2, 3);
        Coordinate translated = translate(origin, 4, 5);
        System.out.println("Method called successfully");
        System.out.println("Returned coordinate: (" + translated.x + ", " + translated.y + ")");
    }
}

