    static class FormatterService {
        public String formatResult(int val) {
            return "Processed: " + val;
        }
    }

    public static void main(String[] args) {
        // Static call via class qualification (invokestatic)
        int factor = MathService.getMultiplier();

        // Instance call via live heap reference (invokevirtual)
