import java.util.Optional;

public class Solution {
    public static Optional<Integer> findFirstNegative(int[] arr) {
        if (arr == null) return Optional.empty();
        for (int val : arr) {
            if (val < 0) {
                return Optional.of(val);
            }
        }
        return Optional.empty();
    }

    public static void main(String[] args) {
        int[] numbersWithNeg = {10, 5, -8, 20};
        int[] numbersAllPos = {10, 5, 8, 20};

        Optional<Integer> opt1 = findFirstNegative(numbersWithNeg);
        Optional<Integer> opt2 = findFirstNegative(numbersAllPos);

        System.out.println("Found: " + opt1.orElse(0));
        System.out.println("Empty case handled: " + opt2.orElse(-1));
    }
}

public class Solution {
    public static String classifyScore(int score) {
        if (score < 0 || score > 100) {
            return "INVALID";
        }
        if (score >= 90) return "A";
        if (score >= 80) return "B";
        if (score >= 70) return "C";
        if (score >= 60) return "D";
        return "F";
    }

    public static void main(String[] args) {
        System.out.println("Score 95: " + classifyScore(95));
        System.out.println("Score 82: " + classifyScore(82));
        System.out.println("Score 55: " + classifyScore(55));
        System.out.println("Score 105: " + classifyScore(105));
    }
}

public class Solution {
    public static int sumDigits(int n) {
        n = Math.abs(n);
        if (n < 10) {
            return n;
        }
        return (n % 10) + sumDigits(n / 10);
    }

    public static void main(String[] args) {
        int number = 1234;
        System.out.println("Number: " + number);
        System.out.println("Sum of digits: " + sumDigits(number));
    }
}

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class Solution {
    static class SecurityContext {
        private final List<String> permissions = new ArrayList<>();

        public SecurityContext() {
            permissions.add("READ");
            permissions.add("WRITE");
        }

        // Vulnerable: returns direct reference
        public List<String> getPermissionsVulnerable() {
            return permissions;
        }

        // Secure: returns unmodifiable view
        public List<String> getPermissionsSecure() {
            return Collections.unmodifiableList(permissions);
        }
    }

    public static void main(String[] args) {
        SecurityContext context = new SecurityContext();

        // Mutating through secure getter
        List<String> secureView = context.getPermissionsSecure();
        try {
            secureView.add("SUPER_ADMIN");
        } catch (UnsupportedOperationException e) {
            System.out.println("Modification blocked by unmodifiable view!");
        }

        System.out.println("Internal permissions preserved: " + context.getPermissionsSecure());
    }
}

import java.util.function.Function;

public class Solution {
    public static Function<Integer, Integer> makeMultiplier(int factor) {
        return x -> x * factor; // Returns a functional closure capturing factor
    }

    public static void main(String[] args) {
        Function<Integer, Integer> doubler = makeMultiplier(2);
        Function<Integer, Integer> tripler = makeMultiplier(3);

        int val1 = doubler.apply(5);
        int val2 = tripler.apply(5);

        System.out.println("Doubler output for 5: " + val1);
        System.out.println("Tripler output for 5: " + val2);
    }
}
